function isMinor(d){if(!d)return false;const b=new Date(d),n=new Date();let a=n.getFullYear()-b.getFullYear(),m=n.getMonth()-b.getMonth();if(m<0||(m===0&&n.getDate()<b.getDate()))a--;return a<18}
async function queueClubEmailEvent(eventType,payload={}){
  try{
    const {error}=await sb.rpc('queue_club_email_event_v820',{
      p_event_type:eventType,
      p_payload:payload
    });
    if(error)console.warn('Email queue:',error.message);
  }catch(e){console.warn('Email queue unavailable',e)}
}

