function signupAgeFromDob(dob){
  if(!dob)return null;
  const parts=dob.split('-');
  if(parts.length!==3)return null;
  const y=Number(parts[0]),m=Number(parts[1]),d=Number(parts[2]);
  if(!y||!m||!d)return null;
  const today=new Date();
  let age=today.getFullYear()-y;
  const monthDiff=(today.getMonth()+1)-m;
  if(monthDiff<0 || (monthDiff===0 && today.getDate()<d))age--;
  return age;
}
function updateSignupMinorNotice(){
  const input=el('signupDob');
  const notice=el('signupMinorNotice');
  if(!input||!notice)return;
  const age=signupAgeFromDob(input.value);
  notice.classList.toggle('hidden', age===null || age>=18);
}
function togglePassword(id,btn){const x=el(id);if(!x)return;x.type=x.type==='password'?'text':'password';if(btn)btn.textContent=x.type==='password'?'SHOW':'HIDE'}
async function loadHomeTrainingOptions(){
  const target=el('homeTrainingOptionsDynamic');if(!target)return;
  const{data,error}=await sb.rpc('public_list_home_training_options');
  if(error||!data||!data.length){target.innerHTML='<div class="muted">Training options currently unavailable.</div>';return}
  target.innerHTML=`<div class="grid3">${data.map(o=>`<div class="plan"><strong>${esc(o.name)}</strong><div class="price">AED ${Number(o.price_aed||0).toFixed(0)}</div><div>${Number(o.sessions||1)} ${Number(o.sessions||1)===1?'session':'sessions'}</div>${o.description?`<div class="muted">${esc(o.description)}</div>`:''}</div>`).join('')}</div>`;
}
async function initHome(){
  await loadHomeTrainingOptions();
  const hasSession=await loadSession(false);
  if(hasSession){
    await loadSession(true);
    return;
  }
  showHome();
}
initHome();

document.addEventListener('DOMContentLoaded',()=>{
  const src=el('managementAlerts');
  if(src){
    const obs=new MutationObserver(syncTechnicalAlerts);
    obs.observe(src,{childList:true,subtree:true,characterData:true});
  }
  const cnt=el('managementAlertCount');
  if(cnt){
    const obs2=new MutationObserver(syncTechnicalAlerts);
    obs2.observe(cnt,{childList:true,subtree:true,characterData:true});
  }
  syncTechnicalAlerts();
});